import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M0 1a1 1 0 0 1 1-1h4a1 1 0 0 1 0 2H2v3a1 1 0 0 1-2 0zm1 15a1 1 0 0 1-1-1v-4a1 1 0 1 1 2 0v3h3a1 1 0 1 1 0 2zm14 0a1 1 0 0 0 1-1v-4a1 1 0 1 0-2 0v3h-3a1 1 0 1 0 0 2zm0-16a1 1 0 0 1 1 1v4a1 1 0 1 1-2 0V2h-3a1 1 0 1 1 0-2zM8 11a3 3 0 1 0 0-6 3 3 0 0 0 0 6"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M0 1a1 1 0 0 1 1-1h5a1 1 0 0 1 0 2H2v4a1 1 0 0 1-2 0zm1 19a1 1 0 0 1-1-1v-5a1 1 0 1 1 2 0v4h4a1 1 0 1 1 0 2zm18 0a1 1 0 0 0 1-1v-5a1 1 0 1 0-2 0v4h-4a1 1 0 1 0 0 2zm0-20a1 1 0 0 1 1 1v5a1 1 0 1 1-2 0V2h-4a1 1 0 1 1 0-2zm-9 14a4 4 0 1 0 0-8 4 4 0 0 0 0 8"] as readonly string[];

export const ClipIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="clip" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
ClipIcon.displayName = `Blueprint6.Icon.ClipIcon`;

/**
 * @deprecated Use {@link ClipIcon} instead.
 */
export const Clip: typeof ClipIcon = ClipIcon;

export default ClipIcon;
